"""Small spectral library for spectrophotometric colour calibration (SPCC).

Everything lives on one wavelength grid, ``WL`` = 330-1100 nm in 1 nm steps.

Curves
------
* Built-in curves: ``astroforge/data/spectra/curves.csv`` (generated by ``build_curves.py`` next to it).
  They are APPROXIMATIONS drawn through publicly documented band edges and peaks, NOT manufacturer
  data: Sony colour sensor R/G/B (IMX071 / IMX294 class, QHY168C), Panasonic MN34230 colour (QHY163C),
  QE shapes (MN34230 mono, Sony FSI colour silicon, Sony BSI mono), filters (UV/IR cut, Optolong
  L-Pro / L-eNhance / L-eXtreme, Baader and Astronomik L/R/G/B, Ha / OIII / SII 7 nm).
* Legacy sensors ``generic_cmos``, ``generic_dslr`` (Gaussians) and ``rgb_filters`` (top-hats) reproduce
  the responses used by AstroForge before the library existed.
* User curves: CSV files in ``~/.astroforge/spectra`` (or ``$ASTROFORGE_SPECTRA``) override or add curves.
  ``name.csv`` with two columns (wavelength, value) is a filter / QE curve called ``name``; four columns
  (wavelength, R, G, B) is a colour sensor called ``name``. Lines starting with ``#`` and a non-numeric
  header line are skipped; wavelengths in Angstrom (> 2000) and values in percent (max > 1.5) are
  converted. Values outside the file's wavelength range are 0.

Spectra
-------
* Stars: black body at the Gaia BP-RP temperature (Mucciarelli & Bellazzini 2020 dwarf relation,
  [Fe/H] = 0, within its 0.39-1.50 validity range; outside, the Pecaut & Mamajek dwarf colour sequence),
  times a crude line-blanketing term that removes blue/UV flux (stronger for cooler stars, equal to the
  solar one at 5772 K, absent above 9000 K). Interstellar reddening is ignored.
* White references: ``G2V`` = the same model at 5772 K (a solar spectrum approximation: Planck with the
  solar blue/UV deficit). ``average_spiral`` = a population mix of such stars from 3500 to 10000 K
  weighted (flux at 550 nm) so the integrated light has the broad SED of a typical Sb/Sc galaxy
  (B-V ~ 0.69, flatter than a single black body: more UV from hot stars, more red from K/M giants).
  This replaces the old single 5150 K black body.

All spectra are photon spectral densities in arbitrary units (SPCC only uses ratios).
"""
import os
from pathlib import Path

import numpy as np

DATA = Path(__file__).parent / "data" / "spectra" / "curves.csv"
USER_DIR = Path.home() / ".astroforge" / "spectra"

WL = np.arange(330.0, 1101.0, 1.0)
DL = 1.0  # nm

NARROWBAND_WIDTH = 60.0   # nm of equivalent width below which a filter set counts as narrowband

# ------------------------------------------------------------------ curve storage


def _read_csv(path):
    rows, names = [], None
    for ln in Path(path).read_text(errors="replace").splitlines():
        s = ln.strip()
        if not s or s.startswith("#"):
            continue
        parts = [p.strip() for p in s.replace(";", ",").replace("\t", ",").split(",")]
        if len(parts) == 1:
            parts = s.split()
        try:
            rows.append([float(p) for p in parts])
        except ValueError:
            if names is None and not rows:
                names = parts
            continue
    if not rows:
        raise ValueError(f"{path}: no numeric rows")
    n = min(len(r) for r in rows)
    return names, np.array([r[:n] for r in rows], float)


def _resample(wl, val):
    wl, val = np.asarray(wl, float), np.asarray(val, float)
    if np.nanmedian(wl) > 2000:   # Angstrom
        wl = wl / 10.0
    order = np.argsort(wl)
    wl, val = wl[order], val[order]
    if np.nanmax(val) > 1.5:      # percent
        val = val / 100.0
    out = np.interp(WL, wl, val, left=0.0, right=0.0)
    return np.clip(np.nan_to_num(out), 0.0, None)


def _legacy_sensors():
    def g(c, s):
        return np.exp(-0.5 * ((WL - c) / s) ** 2)

    def t(lo, hi):
        edge = 1 / (1 + np.exp(-np.clip((WL - lo) / 3, -500, 500))) / (1 + np.exp(np.clip((WL - hi) / 3, -500, 500)))
        return edge * (0.6 + 0.4 * np.exp(-0.5 * ((WL - 530) / 150) ** 2))

    return {
        "generic_cmos": {"R": g(605, 32), "G": g(532, 38), "B": g(462, 30)},
        "generic_dslr": {"R": g(595, 25), "G": g(530, 35), "B": g(465, 28)},
        "rgb_filters": {"R": t(590, 690), "G": t(495, 580), "B": t(400, 505)},
    }


SENSORS = {}      # name -> {"R","G","B": array, "qe": native QE name, "label": str}
QE = {}           # name -> array
FILTERS = {}      # name -> array
USER_CURVES = []  # names loaded from the user directory

LABELS = {
    "generic_cmos": "generic Bayer CMOS (Gaussian approximation, legacy default)",
    "generic_dslr": "generic DSLR (Gaussian approximation)",
    "rgb_filters": "mono + generic RGB filters (legacy top-hats)",
    "sony_color": "Sony colour sensor R/G/B (IMX071 / IMX294 class, e.g. QHY168C)",
    "panasonic_color": "Panasonic MN34230 colour (QHY163C / ASI1600MC)",
    "mono_baader_rgb": "mono camera + Baader R/G/B (QE from the qe parameter, 'sensor' = MN34230 mono)",
    "mono_astronomik_rgb": "mono camera + Astronomik Deep-Sky R/G/B ('sensor' QE = MN34230 mono)",
}


def load(user_dir=None):
    """(Re)load built-in and user curves into SENSORS / QE / FILTERS."""
    SENSORS.clear(), QE.clear(), FILTERS.clear(), USER_CURVES.clear()
    for name, ch in _legacy_sensors().items():
        SENSORS[name] = {**ch, "qe": "ideal"}
    names, arr = _read_csv(DATA)
    sensors = {}
    for i, n in enumerate(names[1:], start=1):
        kind, _, rest = n.partition(":")
        curve = _resample(arr[:, 0], arr[:, i])
        if kind == "sensor":
            s, _, c = rest.partition(":")
            sensors.setdefault(s, {"qe": "ideal"})[c] = curve
        elif kind == "qe":
            QE[rest] = curve
        elif kind == "filter":
            FILTERS[rest] = curve
    SENSORS.update(sensors)
    for brand in ("baader", "astronomik"):
        SENSORS[f"mono_{brand}_rgb"] = {c: FILTERS[f"{brand}_{c.lower()}"] for c in "RGB"} | {"qe": "mn34230_mono"}
    QE["ideal"] = np.ones_like(WL)
    udir = Path(user_dir or os.environ.get("ASTROFORGE_SPECTRA") or USER_DIR)
    if udir.is_dir():
        for p in sorted(udir.glob("*.csv")):
            try:
                hdr, a = _read_csv(p)
            except (OSError, ValueError):
                continue
            name = p.stem.lower().replace(" ", "_")
            if a.shape[1] >= 4:
                SENSORS[name] = {c: _resample(a[:, 0], a[:, i + 1]) for i, c in enumerate("RGB")} | {"qe": "ideal"}
            elif a.shape[1] >= 2:
                curve = _resample(a[:, 0], a[:, 1])
                (QE if name.startswith("qe_") or name in QE else FILTERS)[name] = curve
            else:
                continue
            USER_CURVES.append(name)
    return SENSORS


def sensor_names():
    return list(SENSORS)


def filter_names():
    return ["none"] + list(FILTERS)


def qe_names():
    return ["sensor"] + list(QE)


def curve(name):
    """A single named curve (filter or QE) on WL, or an array passed through."""
    if not isinstance(name, str):
        a = np.asarray(name, float)
        if a.shape != WL.shape:
            raise ValueError(f"curve must have {len(WL)} samples on spectra.WL")
        return a
    key = name.strip().lower()
    if key in ("", "none", "ideal"):
        return np.ones_like(WL)
    if key in FILTERS:
        return FILTERS[key]
    if key in QE:
        return QE[key]
    raise KeyError(f"unknown curve '{name}'. Filters: {', '.join(FILTERS)}; QE: {', '.join(QE)}")


def combine(*curves):
    """Product of curves (names or arrays), like PixInsight Filter Manager 'combine'."""
    out = np.ones_like(WL)
    for c in curves:
        for item in _split(c):
            out = out * curve(item)
    return out


def _split(filters):
    if filters is None:
        return []
    if isinstance(filters, str):
        return [f for f in filters.replace("*", "+").replace(",", "+").split("+") if f.strip()]
    if isinstance(filters, np.ndarray):
        return [filters]
    return [x for f in filters for x in _split(f)]


def response(sensor="generic_cmos", filters=None, qe="sensor"):
    """Effective R, G, B responses (3, len(WL)) = sensor channel x filters x QE.

    qe: 'sensor' = the sensor's native QE ('ideal' for colour sensors, whose R/G/B curves already include
    the silicon response, like the PixInsight Sony Color Sensor curves; MN34230 mono for mono_* sensors),
    'ideal' = 1, or a QE curve name."""
    if sensor not in SENSORS:
        raise KeyError(f"unknown sensor '{sensor}'. Available: {', '.join(SENSORS)}")
    s = SENSORS[sensor]
    q = curve(s["qe"] if qe in (None, "sensor") else qe)
    f = combine(filters)
    return np.stack([s[c] * f * q for c in "RGB"])


def equivalent_width(filters):
    """Equivalent width in nm (integral of transmission / peak) of a filter combination; inf for none."""
    if not _split(filters):
        return float("inf")
    f = combine(filters)
    return float(f.sum() * DL / max(f.max(), 1e-12))


def is_narrowband(filters):
    return equivalent_width(filters) < NARROWBAND_WIDTH


# ------------------------------------------------------------------ stellar spectra

# (BP-RP, Teff) of the dwarf sequence outside the Mucciarelli & Bellazzini validity range
# (Pecaut & Mamajek 2013, "A Modern Mean Dwarf Stellar Color and Effective Temperature Sequence")
_MAMAJEK_BLUE = [(-0.33, 35000), (-0.30, 31400), (-0.20, 17000), (-0.17, 15700), (-0.11, 12500),
                 (0.00, 9700), (0.15, 8080), (0.25, 7650)]
_MAMAJEK_RED = [(1.69, 4050), (1.84, 3850), (2.19, 3560), (2.47, 3430), (2.85, 3210), (3.21, 3060), (3.80, 2810)]


def _mb2020(c):
    """Mucciarelli & Bellazzini 2020 (dwarfs, BP-RP, [Fe/H] = 0): theta = 5040 / Teff."""
    return 5040.0 / (0.4929 + 0.5092 * c - 0.0353 * c ** 2)


def _teff_table():
    from scipy.interpolate import PchipInterpolator
    mid = np.arange(0.40, 1.501, 0.1)
    x = np.r_[[p[0] for p in _MAMAJEK_BLUE], mid, [p[0] for p in _MAMAJEK_RED]]
    y = np.r_[[p[1] for p in _MAMAJEK_BLUE], _mb2020(mid), [p[1] for p in _MAMAJEK_RED]]
    return PchipInterpolator(x, np.log(y)), x[0], x[-1]


_TEFF = None


def bp_rp_to_teff(bp_rp):
    """Gaia BP-RP -> Teff for dwarfs (monotonic, clipped to -0.33..3.8 mag)."""
    global _TEFF
    if _TEFF is None:
        _TEFF = _teff_table()
    f, lo, hi = _TEFF
    return np.exp(f(np.clip(np.asarray(bp_rp, float), lo, hi)))


def planck_photons(teff, wl=None):
    """Photon spectral radiance (arbitrary units): shape (N, len(wl))."""
    wl = WL if wl is None else np.asarray(wl, float)
    t = np.atleast_1d(np.asarray(teff, float))[:, None]
    lam = wl[None, :] * 1e-9
    x = np.minimum(1.4387769e-2 / (lam * t), 700)
    return 1.0 / (lam ** 4 * np.expm1(x))


# solar blue/UV flux deficit relative to a 5772 K black body (line blanketing + Balmer/H- edges), approx.
_BLANKET = np.interp(WL, [330, 360, 380, 400, 420, 440, 460, 480, 500, 550, 600, 700],
                     [0.45, 0.38, 0.30, 0.18, 0.14, 0.08, 0.04, 0.03, 0.02, 0.01, 0.0, 0.0])
SUN_TEFF = 5772.0


def star_spectrum(teff):
    """Model photon spectrum (N, len(WL)): black body x line blanketing scaled with temperature."""
    t = np.atleast_1d(np.asarray(teff, float))
    a = np.clip((9000.0 - t) / (9000.0 - SUN_TEFF), 0.0, 2.0)[:, None]
    return planck_photons(t) * np.clip(1.0 - a * _BLANKET[None, :], 0.05, 1.0)


# Sb/Sc population mix: (Teff, fraction of the flux at 550 nm). Hot young stars dominate the blue,
# K/M giants the red; the sum has B-V ~ 0.69 (0.04 redder than the Sun) and a redder V-R, like the
# Sb/Sc templates used for galaxy white references.
SPIRAL_MIX = [(3500, 0.06), (4000, 0.12), (4500, 0.16), (5000, 0.16), (5500, 0.14), (6000, 0.11),
              (7000, 0.10), (8500, 0.08), (10000, 0.07)]


def white_reference(name="average_spiral"):
    """White reference photon spectrum on WL."""
    key = name.lower()
    if key in ("g2v", "sun", "solar"):
        return star_spectrum(SUN_TEFF)[0]
    if key in ("average_spiral", "spiral", "galaxy"):
        i550 = int(np.argmin(np.abs(WL - 550)))
        out = np.zeros_like(WL)
        for t, w in SPIRAL_MIX:
            s = star_spectrum(t)[0]
            out += w * s / s[i550]
        return out
    raise KeyError(f"unknown white reference '{name}' (G2V, average_spiral)")


WHITE_REFERENCES = ["average_spiral", "G2V"]


def fluxes(spectra, resp):
    """Integrated photon flux (N, 3) of spectra (N, len(WL)) through responses (3, len(WL))."""
    return np.atleast_2d(spectra) @ np.asarray(resp).T * DL


def expected_ratios(bp_rp, sensor="generic_cmos", white="G2V", filters=None, qe="sensor"):
    """Expected R/G and B/G (columns 0 and 2, column 1 = 1) of Gaia stars relative to the white reference."""
    resp = response(sensor, filters, qe)
    f = fluxes(star_spectrum(bp_rp_to_teff(bp_rp)), resp)
    ref = fluxes(white_reference(white), resp)[0]
    f = f / np.maximum(ref, 1e-300)
    return f / f[:, 1:2]


load()
